<!--vbase-->
<template>
  <q-icon
    class="text-red-13 auto_testing q-ma-sm"
    size="sm"
    @click="saveData()"
    v-if="isAutoTestingOn"
  >
    <img width="24" src="../assets/autotesting.png" />
    <q-tooltip>Auto Testing</q-tooltip>
  </q-icon>

  <q-icon
    class="text-red-13 auto_testing q-ma-sm"
    size="sm"
    @click="getDocumentData()"
    v-if="isAutoTestingOn"
  >
    <img width="24" src="../assets/autotesting.png" />
    <q-tooltip>Get Testing Data</q-tooltip>
  </q-icon>
</template>

<script lang="ts">
import axios from 'axios';
import { defineComponent, ref } from 'vue';
import helperMixin from '../mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { dynamicObj } from 'src/pages/assets.js';
import { api, getAuthorizationToken } from 'pages/APIs';
import { notify } from 'src/components/notifications/notify';
import {
  addOrgIdQueryString,
  getOrgId,
} from 'src/utils/organization/org_id_helper';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: {},
  components: {},
  emits: ['setApiData'],
  data() {
    return {};
  },
  computed: {
    isAutoTestingOn: function () {
      let value = false;
      if (this.$route.query && this.$route.query.auto_testing === 'true') {
        value = true;
      }
      return value;
    },
  },
  mounted: function () {
    this.docId = this.$route.params.id as string;
  },
  methods: {
    async saveData() {
      try {
        let response: any;

        this.showLoading();
        let formData = new FormData();
        formData.append('doc_id', this.docId);
        formData.append('org_id', getOrgId());
        let token: string = await getAuthorizationToken();
        response = await axios.post(
          api.auto_test_add_update_document,
          formData,
          {
            headers: {
              Authorization: token,
            },
          },
        );

        if (response.data.success === false) {
          throw response;
        } else {
          notify.success(response.data.message);
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    async getDocumentData() {
      try {
        let response: any;

        this.showLoading();
        let token: string = await getAuthorizationToken();
        response = await axios.get(
          addOrgIdQueryString(api.get_document_data + '?doc_id=' + this.docId),
          {
            headers: {
              Authorization: token,
            },
          },
        );

        if (response.data.success === false) {
          throw response;
        } else {
          notify.success(this.$t('TEST_DATA_LOADED'));
          this.$emit('setApiData', response.data.data);
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },
  setup() {
    return {
      docId: ref(''),
    };
  },
});
</script>

<style lang="scss" scoped>
.auto_testing {
  cursor: pointer;
}
</style>
